// Normalise vendor-specific shapes into one alert object and drop noise
// before it costs any LLM tokens.
const SEVERITY_FLOOR = ['low', 'medium', 'high', 'critical'];
const out = [];

for (const item of $input.all()) {
  const b = item.json.body ?? item.json;

  const severity = String(
    b.severity ?? b.priority ?? b.risk_level ?? 'medium'
  ).toLowerCase();

  const alert = {
    title: b.title ?? b.rule_name ?? b.name ?? b.signature ?? 'Untitled alert',
    severity,
    detected_at: b.detected_at ?? b.timestamp ?? new Date().toISOString(),
    source_system: b.source_system ?? b.vendor ?? 'unknown',
    host: b.host ?? { hostname: b.hostname, ip: b.src_ip ?? b.source_ip },
    user: b.user ?? { username: b.username ?? b.user_name },
    detail: b.detail ?? b.description ?? b.message ?? '',
    raw: b,
  };

  // Suppress anything below the floor; tune this to your alert volume.
  if (!SEVERITY_FLOOR.includes(severity)) continue;

  out.push({ json: { alert, source: 'n8n', dedupe_key: `${alert.title}|${alert.host?.hostname ?? ''}` } });
}

return out;
